  "status": "SUPPORTED",
  "claim": {
    "component_id": "C042.main",
    "value": "Complete histories do not prove that reporting is truthful.",
    "scope": "An evidential limit of documentary completeness.",
    "provenance": {
      "refs": [
        {
          "source_id": "P021",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P021 directly states the identified limit."
    }
  },
  "signal_basis": {
    "component_id": "C042.signal_basis",
    "value": "An internally consistent history connects account creation through publication, distinguishing reported offline activity from logged events and labeling retrospective reports and unknowns.",
    "scope": "Proposed observations for a bounded cohort of new accounts, assumed to occur for this warrant judgment.",
    "provenance": {
      "refs": [
        {
          "source_id": "P012",
          "role": "SUPPORT"
        },
        {
          "source_id": "P004",
          "role": "SUPPORT"
        },
        {
