          "role": "CONTEXT"
        },
        {
          "source_id": "P016",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited bundle supplies the continuity signal, treatment of customer reports, bounded cohort and proposed-observation qualifier."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C042.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The supported evidential limit requires no unresolved empirical relation."
    }
  },
  "rationale": "Completeness and internal consistency concern the recorded history. A complete, consistent history can still contain false reports, so the assumed signal does not establish reporting truthfulness. The claim correctly states that limit.",
  "uncertainty": "Whether particular reports are truthful remains unknown; that does not undermine the stated evidential limit.",
  "anomalies": []
}
